[
  {
    "title": "misaligned-half-points",
    "claim": "In 07-phone-result.png, the denominator of HasanAbi’s half-point fraction drops below the adjacent whole-number baseline in both the HUD and result score.",
    "reason": "The stacked digits make a single mixed score harder to read quickly.",
    "suggest": "Use a compact inline ½ glyph aligned with the whole number in both locations."
  },
  {
    "title": "displaced-impact-streak",
    "claim": "In 11-phone-impact.png, white particles extend from above Asmongold’s head to his belt, while HasanAbi’s kicking foot meets his neck and shoulder.",
    "reason": "The effect obscures where the strike actually connects.",
    "suggest": "Center a compact particle burst at the foot’s contact point and shorten its vertical trails."
  },
  {
    "title": "small-phone-labels",
    "claim": "At the stated 390×844 viewport, the visible letters in the fighter names and stick captions in 02-phone-fight.png are roughly 10–12 pixels tall.",
    "reason": "Players must read these labels while watching the fight on a small screen.",
    "suggest": "Set label fonts to at least 18 CSS pixels and help text to 20 pixels, adjusting spacing and wrapping."
  },
  {
    "title": "inconsistent-combination-notation",
    "claim": "In 05-phone-techref.png, the header places “+” between Stance and Technique, but the move rows place “+” after both stick diagrams.",
    "reason": "The rows contradict the notation used to explain how commands combine.",
    "suggest": "Render each row as stance diagram, plus sign, technique diagram, then move name."
  },
  {
    "title": "controls-outsize-fighters",
    "claim": "In 21-phone-kick-open.png, each joystick is approximately 168 CSS pixels across while each fighter is approximately 130 CSS pixels tall.",
    "reason": "The controls dominate the view while the smaller fighters make poses harder to distinguish.",
    "suggest": "Limit portrait camera zoom-out to keep fighters at least 170 CSS pixels tall while preserving the sticks’ touch areas."
  }
]
